export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function polish(raw){const text=raw.trim().replace(/\s+/g,' ').replace(/^(?:(?:ну|так)[, ]+|(?:мне (?:нужно|надо)|нужно|надо|я хочу|не забыть)\s+)+/iu,'').trim();return text?text[0].toUpperCase()+text.slice(1):''}
const e=escapeHTML;
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shift=(d,n)=>{const x=new Date(d+'T12:00');x.setDate(x.getDate()+n);return dateKey(x)};
const pretty=d=>new Date(d+'T12:00').toLocaleDateString('ru',{day:'numeric',month:'long'});
export const duration=n=>n>=60?`${Math.floor(n/60)} ч${n%60?' '+n%60+' мин':''}`:`${n} мин`;
let view='day',query='',lastUndo=null;const openDetails=new Set();
export function resetDiaryView(){view='day';query=''}
const taskWord=n=>n%100>=11&&n%100<=14?'дел':n%10===1?'дело':n%10>=2&&n%10<=4?'дела':'дел';
export function selectTasks(tasks,date,mode='day',text=''){const now=dateKey(new Date());return tasks.filter(t=>mode==='history'?true:mode==='overdue'?t.day&&t.day<now&&t.mark!=='Сделано':mode==='inbox'?!t.day:mode==='important'?t.priority==='high':t.day===date).filter(t=>!text||[t.title,t.note,t.area].join(' ').toLowerCase().includes(text.toLowerCase())).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')||(b.priority==='high')-(a.priority==='high'));}
export function dayStats(tasks,date){const list=tasks.filter(t=>t.day===date);return {total:list.length,done:list.filter(t=>t.mark==='Сделано').length,minutes:list.filter(t=>t.mark!=='Сделано').reduce((s,t)=>s+(Number(t.minutes)||0),0),untimed:list.filter(t=>t.mark!=='Сделано'&&!Number(t.minutes)).length}}
export function mergeChecklist(text,old=[]){const pool=[...old];return text.split('\n').map(s=>s.trim()).filter(Boolean).map(title=>{const i=pool.findIndex(x=>x.title===title);return i>=0?pool.splice(i,1)[0]:{id:crypto.randomUUID(),title,done:false}})}
function taskHTML(t,date){const done=t.mark==='Сделано',sub=t.checklist||[];return `<article class="agenda-task ${done?'is-done':''} ${t.priority==='high'?'is-important':''}"><button class="task-toggle ${done?'is-checked':''}" data-diarycheck="${e(t.id)}" aria-label="${done?'Вернуть в план':'Выполнить'}: ${e(t.title)}" aria-pressed="${done}">${done?'✓':''}</button><div class="agenda-body"><button class="agenda-title" data-diaryedit="${e(t.id)}">${e(t.title)}</button><div class="agenda-meta">${t.time?`<span class="time-pill">${e(t.time)}</span>`:''}${t.minutes?`<span>${duration(Number(t.minutes))}</span>`:''}${view!=='day'&&t.day?`<span>${pretty(t.day)}</span>`:''}${t.area&&t.area!=='Личное'?`<span class="area-pill">${e(t.area)}</span>`:''}${sub.length?`<span>${sub.filter(s=>s.done).length}/${sub.length} подзадач</span>`:''}${t.mark==='Не сделал'?'<span>Не выполнено</span>':''}</div>${t.note||sub.length?`<details class="agenda-details" data-detail="${e(t.id)}" ${openDetails.has(t.id)?'open':''}><summary>${sub.length?'Подзадачи и заметки':'Заметка'}</summary>${t.note?`<p>${e(t.note)}</p>`:''}${sub.map(s=>`<label class="subtask"><input type="checkbox" data-subtask="${e(s.id)}" data-parent="${e(t.id)}" ${s.done?'checked':''}>${e(s.title)}</label>`).join('')}</details>`:''}</div>${!done?`<button class="reschedule-task" data-reschedule="${e(t.id)}" aria-label="Перенести: ${e(t.title)}">↗</button>`:''}<button class="star-task ${t.priority==='high'?'starred':''}" data-star="${e(t.id)}" aria-label="${t.priority==='high'?'Снять приоритет':'Отметить важным'}" aria-pressed="${t.priority==='high'}">${t.priority==='high'?'★':'☆'}</button></article>`}
function historyHTML(tasks) {
  if (!tasks.length) return '<div class="agenda-empty"><h3>Дела не найдены</h3></div>';
  const byDate = new Map();
  for (const task of tasks) {
    const date = task.day || '';
    if (!byDate.has(date)) byDate.set(date, []);
    byDate.get(date).push(task);
  }
  return [...byDate.keys()].sort().reverse().map(date =>
    `<section class="agenda-section"><h3>${date ? e(new Date(date+'T12:00').toLocaleDateString('ru',{day:'numeric',month:'long',year:'numeric'})) : 'Без даты'}</h3>
    ${byDate.get(date).map(task=>taskHTML(task,date)).join('')}</section>`
  ).join('');
}
function listHTML(state,date){const tasks=selectTasks(state.tasks,date,view,query);if(view==='history')return historyHTML(tasks);const timed=tasks.filter(t=>t.time),loose=tasks.filter(t=>!t.time);return `${!tasks.length?`<div class="agenda-empty"><span>○</span><h3>${query?'Ничего не найдено':view==='inbox'?'Нет дел без даты':view==='overdue'?'Нет незавершённых дел':view==='important'?'Нет важных дел':'На этот день нет дел'}</h3></div>`:''}${timed.length?`<div class="agenda-section"><h3>По времени <span>${timed.length}</span></h3>${timed.map(t=>taskHTML(t,date)).join('')}</div>`:''}${loose.length?`<div class="agenda-section"><h3>${view==='day'?'Без времени':'Задачи'} <span>${loose.length}</span></h3>${loose.map(t=>taskHTML(t,date)).join('')}</div>`:''}`}
export function diaryHTML(state,date,phrase=""){const stats=dayStats(state.tasks,date),now=dateKey(new Date()),weekday=new Date(date+'T12:00').getDay(),monday=shift(date,-((weekday+6)%7)),counts={day:state.tasks.filter(t=>t.day===date).length,important:selectTasks(state.tasks,date,'important').length,overdue:selectTasks(state.tasks,date,'overdue').length,inbox:selectTasks(state.tasks,date,'inbox').length,history:state.tasks.length};const line=state.dayLines?.[date];return `<section class="planner"><div class="day-line"><blockquote id="daily-phrase" data-date="${e(date)}">${line || phrase ? `«${e(line || phrase)}»` : ''}</blockquote><button id="edit-day-line" class="text-btn">${line?'Изменить':'Своя фраза'}</button></div><header class="planner-heading"><div><span class="planner-kicker">01 / ЕЖЕДНЕВНИК</span><h1>${date===now?'Сегодня':pretty(date)}</h1><p>${new Date(date+'T12:00').toLocaleDateString('ru',{weekday:'long',day:'numeric',month:'long'})}</p></div><button id="diary-add" class="primary">＋ Новое дело</button></header><section class="planner-calendar"><div class="calendar-toolbar"><button id="diary-prev" aria-label="Предыдущая неделя">←</button><button id="diary-date" class="date-trigger" aria-label="Выбрать дату">${pretty(date)}</button><button id="diary-next" aria-label="Следующая неделя">→</button></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=shift(monday,i),n=state.tasks.filter(t=>t.day===d&&t.mark!=='Сделано').length;return `<button data-day="${d}" class="week-day ${d===date?'selected':''} ${d===now?'is-today':''}" aria-pressed="${d===date}"><span>${new Date(d+'T12:00').toLocaleDateString('ru',{weekday:'short'})}</span><strong>${Number(d.slice(-2))}</strong><small>${n||'·'}</small></button>`}).join('')}</div><div class="calendar-footer"><button id="diary-today" class="text-btn">Сегодня</button></div></section><div class="planner-stats"><div class="day-summary"><span>Выполнено</span><strong>${stats.done}<small> / ${stats.total}</small></strong><div class="summary-track"><i style="width:${stats.total?100*stats.done/stats.total:0}%"></i></div></div><div class="day-summary lavender"><span>Осталось</span><strong>${stats.total-stats.done}<small> ${taskWord(stats.total-stats.done)}</small></strong><p>на выбранный день</p></div><div class="day-summary peach"><span>Оценка времени</span><strong>${duration(stats.minutes)}</strong><p>${stats.untimed?`${stats.untimed} без оценки времени`:'на оставшиеся дела'}</p></div></div><div class="agenda-panel"><div class="planner-filters">${[['day','День'],['important','Важное'],['overdue','Просрочено'],['inbox','Без даты'],['history','Все дела']].map(([key,label])=>`<button data-filter="${key}" class="${view===key?'active':''}" aria-pressed="${view===key}">${label}<span>${counts[key]}</span></button>`).join('')}</div><form id="quick-capture" class="capture-bar"><input id="capture" aria-label="Новое дело" placeholder="Новое дело" maxlength="1000" autocomplete="off"><button type="button" id="diary-voice" aria-label="Добавить голосом" title="Голосом">◉</button><button class="capture-submit" aria-label="Добавить дело">＋</button></form><div class="agenda-toolbar"><h2>${{day:'План дня',important:'Важные дела',overdue:'Незавершённые дела',inbox:'Без даты',history:'Все дела'}[view]}</h2><input type="search" id="diary-search" aria-label="Поиск в списке" placeholder="Поиск" value="${e(query)}"></div>${view==='overdue'?'<p class="filter-note">Невыполненные дела до сегодняшнего дня.</p>':''}${view==='important'?'<p class="filter-note">Важные дела за все даты.</p>':''}${view==='inbox'?'<p class="filter-note">Добавленные здесь дела сохраняются без даты.</p>':''}<div id="agenda-list">${listHTML(state,date)}</div></div>${lastUndo?'<div class="undo-bar" role="status"><span>Изменение сохранено</span><button id="diary-undo">Отменить</button></div>':''}</section>`}
export function bindDiary({state,date,setDate,today,save,feedback}){const $=s=>document.querySelector(s),draftKey='kontur-capture-'+date;const rerender=()=>setDate(date);try{$('#capture').value=sessionStorage.getItem(draftKey)||''}catch{}$('#capture').oninput=()=>{try{sessionStorage.setItem(draftKey,$('#capture').value)}catch{}};
const clearDraft=()=>{try{sessionStorage.removeItem(draftKey)}catch{}};
const commit=(before,after)=>{const old=lastUndo;const index=before?state.tasks.findIndex(t=>t.id===before.id):state.tasks.length;state.tasks.splice(index,before?1:0,...(after?[after]:[]));lastUndo={index,before:before?structuredClone(before):null,id:(before||after).id};if(!save()){lastUndo=old;return false}return true};
function bindRows(){document.querySelectorAll('[data-reschedule]').forEach(b=>b.onclick=()=>reschedule(state.tasks.find(t=>t.id===b.dataset.reschedule)));document.querySelectorAll('[data-detail]').forEach(d=>d.ontoggle=()=>{if(d.open)openDetails.add(d.dataset.detail);else openDetails.delete(d.dataset.detail)});document.querySelectorAll('[data-diaryedit]').forEach(b=>b.onclick=()=>editor('',state.tasks.find(t=>t.id===b.dataset.diaryedit)));document.querySelectorAll('[data-diarycheck]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.diarycheck);if(commit(t,{...t,mark:t.mark==='Сделано'?'В плане':'Сделано'})){const toggle=document.querySelector('[data-diarycheck="'+CSS.escape(t.id)+'"]');toggle?.focus({preventScroll:true});toggle?.classList.add('just-toggled')}});document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.star);commit(t,{...t,priority:t.priority==='high'?'normal':'high'})});document.querySelectorAll('[data-subtask]').forEach(b=>b.onchange=()=>{const t=state.tasks.find(t=>t.id===b.dataset.parent);commit(t,{...t,checklist:t.checklist.map(x=>x.id===b.dataset.subtask?{...x,done:b.checked}:x)})});}
function reschedule(t){const d=$('#editor');d.onclose=null;d.oncancel=null;d.innerHTML=`<div class="dialog-head"><h2>Перенести дело</h2><button id="move-close" aria-label="Закрыть">✕</button></div><form id="move-form" class="dialog-body"><p>${e(t.title)}</p><div class="move-shortcuts"><button type="button" data-move-date="${today()}">Сегодня</button><button type="button" data-move-date="${shift(today(),1)}">Завтра</button><button type="button" data-move-date="">Без даты</button></div><label>Дата<input name="day" type="date" value="${e(t.day||date)}"></label><button class="primary">Перенести</button></form>`;const move=value=>{if(commit(t,{...t,day:value,time:value?t.time:'',mark:t.mark==='Не сделал'?'В плане':t.mark})){d.close();feedback(value?'Перенесено на '+pretty(value):'Сохранено без даты')}};$('#move-close').onclick=()=>d.close();document.querySelectorAll('[data-move-date]').forEach(b=>b.onclick=()=>move(b.dataset.moveDate));$('#move-form').onsubmit=ev=>{ev.preventDefault();move(new FormData(ev.target).get('day'))};d.showModal()}
function editor(raw='',existing=null,voice=false){const d=$('#editor');let recognition=null;d.innerHTML=`<div class="dialog-head"><h2>${existing?'Дело':'Новое дело'}</h2><button id="diary-close" aria-label="Закрыть">✕</button></div><form id="diary-form" class="dialog-body"><label>Название<textarea name="title" id="result" required maxlength="1000" rows="2" placeholder="Название дела">${e(existing?.title||raw)}</textarea></label><div class="editor-tools"><button type="button" id="voice">◉ Голосом</button><button type="button" id="polish">Сократить</button></div><p id="voice-status" class="small muted" role="status"></p><div class="field-row"><label>Дата<input name="day" type="date" value="${e(existing?existing.day: view==='inbox'?'':date)}"></label><label>Время<input name="time" type="time" value="${e(existing?.time||'')}"></label></div><div class="field-row"><label>Длительность, мин<input name="minutes" type="number" min="0" max="1440" value="${Number(existing?.minutes)||0}"></label><label>Приоритет<select name="priority"><option value="normal">Обычный</option><option value="high" ${existing?.priority==='high'?'selected':''}>Высокий</option></select></label></div><label>Заметка<textarea name="note" rows="3">${e(existing?.note||'')}</textarea></label><label>Подзадачи<textarea name="checklist" rows="3" placeholder="Каждая с новой строки">${e((existing?.checklist||[]).map(x=>x.title).join('\n'))}</textarea></label><label>Статус<select name="mark">${['В плане','Сделано','Не сделал'].map(m=>`<option ${existing?.mark===m?'selected':''}>${m}</option>`).join('')}</select></label><p id="diary-error" class="form-error" role="alert"></p><div class="dialog-actions">${existing?'<button type="button" id="diary-delete" class="danger">Удалить</button>':''}<button class="primary" id="diary-submit">${existing?'Сохранить':'Добавить'}</button></div></form>`;
const stop=()=>{if(recognition){recognition.onend=null;recognition.onresult=null;recognition.onerror=null;recognition.onstart=null;recognition.abort();recognition=null}};d.onclose=stop;d.oncancel=stop;$('#diary-close').onclick=()=>d.close();$('#polish').onclick=()=>{$('#result').value=polish($('#result').value)};
$('#voice').onclick=()=>{if(recognition){recognition.stop();return}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){$('#voice-status').textContent='Используйте микрофон на клавиатуре.';$('#result').focus();return}const base=$('#result').value,r=new Speech();recognition=r;r.lang='ru-RU';r.interimResults=false;r.continuous=false;$('#voice-status').textContent='Распознавание выполняет браузер; аудио может передаваться его сервису.';r.onstart=()=>{$('#voice-status').textContent='Идёт запись · распознавание через сервис браузера';$('#voice').textContent='■ Стоп';$('#diary-submit').disabled=true};r.onresult=ev=>{if(d.open){$('#result').value=[base,Array.from(ev.results).filter(x=>x.isFinal).map(x=>x[0].transcript).join(' ')].filter(Boolean).join(' ');$('#voice-status').textContent='Готово'}};r.onerror=ev=>{if(d.open)$('#voice-status').textContent=ev.error==='not-allowed'?'Нет доступа к микрофону.':ev.error==='no-speech'?'Речь не распознана.':'Диктовка недоступна. Используйте микрофон клавиатуры.'};r.onend=()=>{recognition=null;if(d.open){$('#voice').textContent='◉ Голосом';$('#diary-submit').disabled=false}};try{r.start()}catch{recognition=null;$('#voice-status').textContent='Диктовка недоступна.'}};
if(existing)$('#diary-delete').onclick=()=>{stop();if(commit(existing,null))d.close()};
$('#diary-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),title=String(f.get('title')).trim();if(!title){$('#diary-error').textContent='Укажите название.';return}if(f.get('time')&&!f.get('day')){$('#diary-error').textContent='Для времени нужна дата.';return}const task={...(existing||{}),id:existing?.id||crypto.randomUUID(),title,day:f.get('day'),time:f.get('time'),priority:f.get('priority'),note:f.get('note'),mark:f.get('mark'),area:existing?.area||'Личное',minutes:Number(f.get('minutes')),checklist:mergeChecklist(String(f.get('checklist')),existing?.checklist)};stop();if(commit(existing,task)){clearDraft();$('#capture').value='';d.close()}};d.showModal();$('#result').focus();if(voice)$('#voice').click();}
$('#diary-add').onclick=()=>editor();$('#diary-voice').onclick=()=>editor($('#capture').value,null,true);$('#quick-capture').onsubmit=ev=>{ev.preventDefault();const title=$('#capture').value.trim();if(!title){$('#capture').focus();return}if(commit(null,{id:crypto.randomUUID(),title,day:view==='inbox'?'':date,mark:'В плане',area:'Личное',minutes:0,priority:'normal'})){clearDraft();$('#capture').value='';$('#capture').focus()}};
$('#diary-search').oninput=ev=>{query=ev.target.value;$('#agenda-list').innerHTML=listHTML(state,date);bindRows()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{view=b.dataset.filter;query='';rerender()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{view='day';query='';setDate(b.dataset.day)});$('#diary-date').onclick=()=>{
  const dialog=$('#editor');
  dialog.onclose=null;
  dialog.oncancel=null;
  dialog.innerHTML=`<div class="dialog-head"><h2>Выбрать дату</h2><button id="date-close" aria-label="Закрыть">✕</button></div>
    <form id="date-form" class="dialog-body"><label>Дата<input name="day" type="date" required value="${e(date)}"></label><button class="primary">Открыть день</button></form>`;
  $('#date-close').onclick=()=>dialog.close();
  $('#date-form').onsubmit=event=>{
    event.preventDefault();
    const selected=new FormData(event.currentTarget).get('day');
    if(!selected)return;
    dialog.close();
    resetDiaryView();
    setDate(selected);
  };
  dialog.showModal();
};$('#diary-today').onclick=()=>{resetDiaryView();setDate(today())};for(const [id,n]of [['diary-prev',-7],['diary-next',7]])$('#'+id).onclick=()=>{resetDiaryView();setDate(shift(date,n))};if($('#diary-undo'))$('#diary-undo').onclick=()=>{const undo=lastUndo;state.tasks=state.tasks.filter(t=>t.id!==undo.id);if(undo.before)state.tasks.splice(undo.index,0,undo.before);lastUndo=null;save()};bindRows();}
